package app.studyforge.mobile;

import org.junit.Test;
import static org.junit.Assert.*;
import org.json.*;

public class PastExpansionTest {
    static JSONArray sources() throws Exception {JSONArray list=CoreTest.sources();list.put(Json.object("id","past1","title","답만 남은 족보","role","past","text","답: 틸라코이드 막\n추가 단서: 엽록소","images",new JSONArray()));return list;}
    static JSONObject result() throws Exception {
        JSONObject r=CoreTest.result(),q=r.getJSONArray("questions").getJSONObject(0),fragment=Json.object("source_id","past1","page",1,"quote","답: 틸라코이드 막");
        q.put("kind","past_reconstructed").put("past",Json.object("method","answer_reconstructed","fragment",fragment,"missing",Json.array("질문·보기"),"added",Json.array("장소를 구별하는 질문·보기"),"basis",Json.object("type","materials","text","교재의 명반응 장소와 대조","citations",Json.array(q.getJSONArray("citations").getJSONObject(0))),"confidence","medium","confidence_reason","교재 근거는 있으나 원래 질문은 없음","assumptions",new JSONArray(),"alternatives",Json.array("다른 기능을 물었을 수도 있음"),"source_answer","틸라코이드 막"));
        r.put("past_coverage",Json.array(Json.object("fragment",fragment,"label","답만 남은 항목","status","used","reason","명반응 장소 문제로 재구성","question_indices",Json.array(0)),Json.object("fragment",Json.object("source_id","past1","page",1,"quote","추가 단서: 엽록소"),"label","다음 확장 후보","status","pending","reason","다음 요청에서 색소 역할로 확장 가능","question_indices",new JSONArray())));return r;
    }
    static JSONObject past(JSONObject r) throws Exception {return r.getJSONArray("questions").getJSONObject(0).getJSONObject("past");}
    @Test public void answerOnlyCanBecomeTraceableQuestionWithoutInventedAnswerKey() throws Exception {JSONObject r=PastExpansion.validate(result(),sources(),5);assertEquals(1,r.getJSONArray("questions").length());assertFalse(r.getJSONArray("questions").getJSONObject(0).has("answer_citation"));assertThrows(Exception.class,()->QuestionValidator.validate(result(),sources(),1,true));}
    @Test public void unsupportedAnswerUsesLowConfidenceAndNoFakeCitations() throws Exception {JSONObject r=result();JSONObject p=past(r);p.put("confidence","low").put("basis",Json.object("type","general_knowledge","text","일반 지식에 기초한 제안 답","citations",new JSONArray()));PastExpansion.validate(r,sources(),5);p.put("confidence","high");assertThrows(Exception.class,()->PastExpansion.validate(r,sources(),5));}
    @Test public void inferenceCannotMasqueradeAsOriginalOrAsVerifiedPastEvidence() throws Exception {JSONObject r=result();r.getJSONArray("questions").getJSONObject(0).put("kind","original");assertThrows(Exception.class,()->PastExpansion.validate(r,sources(),5));JSONObject onlyPast=result();past(onlyPast).getJSONObject("basis").put("citations",Json.array(past(onlyPast).getJSONObject("fragment")));assertThrows(Exception.class,()->PastExpansion.validate(onlyPast,sources(),5));JSONObject fabricated=result();past(fabricated).put("source_answer","원문에 없는 답");assertThrows(Exception.class,()->PastExpansion.validate(fabricated,sources(),5));}
    @Test public void coverageMustUseRealFragmentsAndMatchQuestionIndices() throws Exception {JSONObject r=result();r.getJSONArray("past_coverage").getJSONObject(0).put("question_indices",Json.array(3));assertThrows(Exception.class,()->PastExpansion.validate(r,sources(),5));JSONObject fake=result();past(fake).getJSONObject("fragment").put("quote","없는 단서");assertThrows(Exception.class,()->PastExpansion.validate(fake,sources(),5));JSONObject dup=result();dup.getJSONArray("past_coverage").put(dup.getJSONArray("past_coverage").getJSONObject(0));assertThrows(Exception.class,()->PastExpansion.validate(dup,sources(),5));}
    @Test public void everyPastFileMustBeReviewedAndShortAnswerCanBeImported() throws Exception {assertEquals("물",SourceImporter.text("답","물","past").getString("text"));assertThrows(Exception.class,()->SourceImporter.text("교재","물","textbook"));JSONArray extra=sources();extra.put(Json.object("id","past2","role","past","text","남은 단서","images",new JSONArray()));assertThrows(Exception.class,()->PastExpansion.validate(result(),extra,5));assertThrows(Exception.class,()->PastExpansion.requirePast(CoreTest.sources()));}
    @Test public void noAnswerableQuestionCanRemainAsUnusableRatherThanForcedFiller() throws Exception {JSONObject r=result();r.put("questions",new JSONArray());r.getJSONArray("past_coverage").getJSONObject(0).put("status","unusable").put("question_indices",new JSONArray());PastExpansion.validate(r,sources(),5);}
    @Test public void previousQuestionsUseSameSourceAndRepeatsAreRejected() throws Exception {JSONObject r=result();JSONObject d=Json.copy(r);JSONObject workspace=Json.object("dataset",d,"rooms",new JSONArray());JSONArray previous=PastExpansion.previous(workspace,sources());assertEquals(1,previous.length());assertThrows(Exception.class,()->PastExpansion.rejectRepeated(result(),previous));JSONArray other=CoreTest.sources();assertEquals(0,PastExpansion.previous(workspace,other).length());}
    @Test public void resetPreservesQuestionsAndProvenanceButClearsAnswers() throws Exception {JSONObject data=result().put("id","dataset").put("answers",Json.object("q",Json.object("selected",1,"attempts",Json.array(1,2)))).put("uncertain",Json.object("q",true)).put("history",Json.array("old revision"));JSONObject reset=StudyRecords.reset(data);assertEquals(0,reset.getJSONObject("answers").length());assertEquals(0,reset.getJSONObject("uncertain").length());assertEquals(data.getJSONArray("questions").toString(),reset.getJSONArray("questions").toString());assertEquals(data.getJSONArray("history").toString(),reset.getJSONArray("history").toString());assertEquals(1,data.getJSONObject("answers").length());}
}
